import osimport jsonimport timeimport loggingfrom datetime import datetime, date, timedeltafrom typing import Optionalimport requestsimport httpximport redis.asyncio as redisfrom fastapi import FastAPI, Request, HTTPException, Headerfrom fastapi.responses import JSONResponsefrom dotenv import load_dotenvfrom pydantic import BaseModelfrom apscheduler.schedulers.asyncio import AsyncIOSchedulerfrom maxbot.bot import Botfrom maxbot.dispatcher import Dispatcherfrom maxbot.types import Messagefrom database import (    init_db, get_tenant_by_code, get_all_tenants,    save_reminder, get_pending_reminders, mark_reminded,)# ===== Загрузка переменных окружения =====load_dotenv()BOT_TOKEN = os.getenv("BOT_TOKEN")MINIAPP_TUNNEL_URL = os.getenv("MINIAPP_TUNNEL_URL", "")ONEC_BASE_URL = os.getenv("ONEC_BASE_URL")ONEC_USER = os.getenv("ONEC_USER")ONEC_PASSWORD = os.getenv("ONEC_PASSWORD")ONEC_TIMEOUT = int(os.getenv("ONEC_TIMEOUT", "10"))REDIS_HOST = os.getenv("REDIS_HOST", "redis")REDIS_PORT = int(os.getenv("REDIS_PORT", "6379"))REDIS_DB = int(os.getenv("REDIS_DB", "0"))# ===== Рабочие часы =====WORK_START = 9WORK_END = 18LUNCH_START = 13LUNCH_END = 14SESSION_TTL = 3600WEEKDAY_NAMES_RU = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"]# ===== Логирование =====logging.basicConfig(    level=os.getenv("LOG_LEVEL", "INFO").upper(),    format="%(asctime)s [%(levelname)s] %(message)s",)logger = logging.getLogger("max-bot")# ===== Pydantic-модели =====class SlotRequest(BaseModel):    service_id: Optional[str] = None    employee: Optional[str] = None    date: str    tenant_code: Optional[str] = Noneclass BookingRequest(BaseModel):    employee_id: str    date: str    time: str    client_name: str    client_phone: str    tenant_code: Optional[str] = None# ===== Redis =====redis_client: Optional[redis.Redis] = Noneasync def get_state(user_id: int) -> Optional[dict]:    if not redis_client:        return None    data = await redis_client.get(f"state:{user_id}")    return json.loads(data) if data else Noneasync def set_state(user_id: int, state: dict, ttl: int = SESSION_TTL):    if not redis_client:        return    state["_updated_at"] = time.time()    await redis_client.set(f"state:{user_id}", json.dumps(state), ex=ttl)async def del_state(user_id: int):    if not redis_client:        return    await redis_client.delete(f"state:{user_id}")async def get_current_tenant(user_id: int):    state = await get_state(user_id)    if not state:        return None    tenant_code = state.get("tenant_code")    if not tenant_code:        return None    return get_tenant_by_code(tenant_code)# ===== HTTP-клиент =====_http_client: Optional[httpx.AsyncClient] = None# ===== Вызовы 1С =====def call_1c(method: str, payload: Optional[dict] = None, http_method: str = "POST", tenant=None) -> dict:    if tenant:        base_url = tenant.onec_url        auth = (tenant.onec_user, tenant.onec_password) if tenant.onec_user else None    else:        base_url = ONEC_BASE_URL        auth = (ONEC_USER, ONEC_PASSWORD) if ONEC_USER else None    url = f"{base_url}/{method}"    try:        if http_method == "GET":            resp = requests.get(url, auth=auth, params=payload, timeout=ONEC_TIMEOUT)        elif method == "records":            resp = requests.post(url, auth=auth, params=payload, timeout=ONEC_TIMEOUT)        else:            resp = requests.post(url, auth=auth, json=payload, timeout=ONEC_TIMEOUT)        resp.raise_for_status()        return resp.json()    except requests.exceptions.RequestException as e:        logger.error(f"Ошибка вызова 1С ({method}): {e}")        raise HTTPException(status_code=502, detail=f"1С недоступна: {e}")def get_employees(tenant=None) -> list:    try:        data = call_1c("getEmployees", tenant=tenant)        return data if isinstance(data, list) else data.get("employees", [])    except HTTPException:        return []def get_busy_slots(date_str: str, employee_id: Optional[str] = None, tenant=None) -> list:    payload = {"date": date_str}    if employee_id:        payload["employee"] = employee_id    try:        data = call_1c("records", payload, tenant=tenant)        return data if isinstance(data, list) else data.get("slots", [])    except HTTPException:        return []def get_free_slots(date_str: str, employee_id: Optional[str] = None, tenant=None) -> list:    busy = get_busy_slots(date_str, employee_id, tenant)    busy_hours = set()    for s in busy:        t = s.get("time", "")        if t:            busy_hours.add(f"{t.split(':')[0]}:00")    free = []    current = datetime.strptime(f"{date_str} {WORK_START}:00", "%Y-%m-%d %H:%M")    end = datetime.strptime(f"{date_str} {WORK_END}:00", "%Y-%m-%d %H:%M")    while current < end:        slot_str = current.strftime("%H:00")        is_lunch = LUNCH_START <= current.hour < LUNCH_END        if not is_lunch and slot_str not in busy_hours:            free.append(slot_str)        current += timedelta(hours=1)    return free# ===== Отправка в MAX =====async def send_max_message(user_id: int, text: str, attachments: Optional[list] = None):    url = f"https://platform-api2.max.ru/messages?user_id={user_id}"    headers = {        "Authorization": BOT_TOKEN,        "Content-Type": "application/json",    }    payload = {"text": text}    if attachments:        payload["attachments"] = attachments    try:        resp = await _http_client.post(url, headers=headers, json=payload, timeout=10)        logger.info(f"Отправка в MAX: {resp.status_code} {resp.text[:200]}")        return resp.json()    except Exception as e:        logger.error(f"Ошибка отправки в MAX: {type(e).__name__}: {e}")        return None# ===== Клавиатуры =====CANCEL_BUTTON = {"type": "callback", "text": "❌ Отмена", "payload": "cancel"}def make_keyboard(buttons: list, with_cancel: bool = True) -> dict:    rows = [        [{"type": "callback", "text": text, "payload": payload}]        for text, payload in buttons    ]    if with_cancel:        rows.append([CANCEL_BUTTON])    return {        "type": "inline_keyboard",        "payload": {"buttons": rows},    }def make_main_menu() -> dict:    miniapp_url = MINIAPP_TUNNEL_URL or "https://fb910754-a4ef-4cf0-b150-40b9fd3a19d5.tunnel4.com/app/"    rows = [        [            {"type": "open_app", "text": "🚀 Открыть в MAX", "web_app": "t561_hakaton_max_bot"},            {"type": "link", "text": "🌐 Открыть в браузере", "url": miniapp_url},        ],        [{"type": "callback", "text": "🏢 Выбрать заведение", "payload": "menu:choose_tenant"}],        [            {"type": "callback", "text": "📅 Свободные слоты", "payload": "menu:slots"},            {"type": "callback", "text": "✍️ Записаться", "payload": "menu:book"},        ],        [{"type": "callback", "text": "👥 Сотрудники", "payload": "menu:master"}],        [{"type": "callback", "text": "📍 Контакты", "payload": "menu:contacts"}],        [{"type": "callback", "text": "❓ Помощь", "payload": "menu:help"}],    ]    return {        "type": "inline_keyboard",        "payload": {"buttons": rows},    }async def send_main_menu(user_id: int, text: str = "Что вы хотите сделать?"):    await send_max_message(user_id, text, attachments=[make_main_menu()])def get_week_start(d: date) -> date:    return d - timedelta(days=d.weekday())def make_week_calendar_keyboard(week_start: date) -> dict:    today = date.today()    buttons = []    prev_week = week_start - timedelta(days=7)    next_week = week_start + timedelta(days=7)    buttons.append([        {"type": "callback", "text": "◀️", "payload": f"cal_week:{prev_week.strftime('%Y-%m-%d')}"},        {"type": "callback", "text": week_start.strftime("%m.%y"), "payload": "cal_noop"},        {"type": "callback", "text": "▶️", "payload": f"cal_week:{next_week.strftime('%Y-%m-%d')}"},    ])    buttons.append([        {"type": "callback", "text": WEEKDAY_NAMES_RU[i], "payload": "cal_noop"}        for i in range(7)    ])    row = []    for i in range(7):        d = week_start + timedelta(days=i)        if d < today:            row.append({"type": "callback", "text": "·", "payload": "cal_noop"})        else:            row.append({                "type": "callback",                "text": str(d.day),                "payload": f"cal_pick:{d.strftime('%Y-%m-%d')}",            })    buttons.append(row)    buttons.append([CANCEL_BUTTON])    return {        "type": "inline_keyboard",        "payload": {"buttons": buttons},    }# ===== Подсказки команд =====async def set_bot_commands():    url = "https://platform-api2.max.ru/me/commands"    headers = {        "Authorization": BOT_TOKEN,        "Content-Type": "application/json",    }    payload = {        "commands": [            {"name": "start", "description": "Запустить бота"},            {"name": "help", "description": "Список команд"},            {"name": "slots", "description": "Свободные слоты на дату"},            {"name": "today", "description": "Свободные слоты на сегодня"},            {"name": "book", "description": "Создать новую запись"},            {"name": "contacts", "description": "Наши контакты"},            {"name": "master", "description": "Список сотрудников"},            {"name": "cancel", "description": "Отменить действие"},        ]    }    try:        resp = await _http_client.patch(url, headers=headers, json=payload, timeout=10)        logger.info(f"Установка команд: {resp.status_code}")    except Exception as e:        logger.error(f"Ошибка установки команд: {e}")# ===== Бот =====bot = Bot(BOT_TOKEN) if BOT_TOKEN else Nonedp = Dispatcher(bot) if bot else NoneHELP_TEXT = """Доступные команды:/start — приветствие/help — эта справка/slots — свободные слоты на дату/today — свободные слоты на сегодня/book — создать новую запись/contacts — наши контакты/master — список сотрудников/cancel — отменить текущее действие"""def is_valid_date(s: str) -> bool:    s = s.strip().rstrip(".")    try:        datetime.strptime(s, "%Y-%m-%d")        return True    except ValueError:        return Falsedef clean_date(s: str) -> str:    return s.strip().rstrip(".")async def ask_tenant(user_id: int, text: str = "🏢 Выберите заведение:"):    tenants = get_all_tenants()    if not tenants:        await send_max_message(user_id, "❌ Нет доступных заведений.")        return    buttons = [(t.name, f"tenant:{t.code}") for t in tenants]    await send_max_message(user_id, text, attachments=[make_keyboard(buttons, with_cancel=True)])async def show_employees_keyboard(user_id: int, state: dict, tenant):    employees = get_employees(tenant=tenant)    if not employees:        await send_max_message(user_id, "❌ Не удалось получить список сотрудников.")        await del_state(user_id)        await send_main_menu(user_id, "Что дальше?")        return    state["employees"] = employees    state["step"] = "book_employee"    await set_state(user_id, state)    buttons = [(emp["name"], f"emp:{emp['id']}") for emp in employees]    await send_max_message(        user_id,        f"🏢 {tenant.name}\n\nШаг 2/4: выберите сотрудника:",        attachments=[make_keyboard(buttons, with_cancel=True)]    )async def show_times_keyboard(user_id: int, state: dict, tenant):    free = get_free_slots(state["date"], state["employee_id"], tenant)    if not free:        await send_max_message(            user_id,            f"🏢 {tenant.name}\n\nНа {state['date']} у выбранного сотрудника нет свободного времени."        )        await del_state(user_id)        await send_main_menu(user_id, "Что дальше?")        return    state["step"] = "book_time"    await set_state(user_id, state)    buttons = [(t, f"time:{t}") for t in free]    await send_max_message(        user_id,        f"🏢 {tenant.name}\n👤 {state['employee_name']}\n📅 {state['date']}\n\nШаг 3/4: выберите время:",        attachments=[make_keyboard(buttons, with_cancel=True)]    )async def show_week_calendar(user_id: int, week_start: date, title: str = "Выберите дату:", tenant=None):    if tenant:        title = f"🏢 {tenant.name}\n\n{title}"    await send_max_message(        user_id,        title,        attachments=[make_week_calendar_keyboard(week_start)]    )async def handle_slots_request(user_id: int, date_str: str, tenant=None):    if tenant is None:        tenant = await get_current_tenant(user_id)    if not tenant:        await ask_tenant(user_id, "Сначала выберите заведение:")        return    date_str = clean_date(date_str)    if not is_valid_date(date_str):        await send_max_message(user_id, "❌ Неверный формат даты. Используйте ГГГГ-ММ-ДД.")        await send_main_menu(user_id, "Что дальше?")        return    employees = get_employees(tenant=tenant)    if not employees:        await send_max_message(user_id, "Не удалось получить список сотрудников.")        await send_main_menu(user_id, "Что дальше?")        return    lines = [f"🏢 {tenant.name}\n📅 Свободные слоты на {date_str}:"]    for emp in employees:        free = get_free_slots(date_str, emp["id"], tenant)        if free:            lines.append(f"\n👤 {emp['name']}: {', '.join(free)}")        else:            lines.append(f"\n👤 {emp['name']}: нет свободного времени")    await send_max_message(user_id, "\n".join(lines))    await send_main_menu(user_id, "Что дальше?")async def handle_master(user_id: int):    tenant = await get_current_tenant(user_id)    if not tenant:        await ask_tenant(user_id, "Сначала выберите заведение:")        return    employees = get_employees(tenant=tenant)    if not employees:        await send_max_message(user_id, "❌ Не удалось получить список сотрудников.")    else:        lines = [f"🏢 {tenant.name}\n👥 Список сотрудников:"]        for emp in employees:            lines.append(f"• {emp['name']} (код: {emp['id']})")        await send_max_message(user_id, "\n".join(lines))    await send_main_menu(user_id, "Что дальше?")async def handle_contacts(user_id: int):    tenant = await get_current_tenant(user_id)    if not tenant:        await ask_tenant(user_id, "Сначала выберите заведение:")        return    text = f"🏢 {tenant.name}\n\n📍 Контакты:\n"    if tenant.address:        text += f"Адрес: {tenant.address}\n"    if tenant.phone:        text += f"Телефон: {tenant.phone}\n"    await send_max_message(user_id, text)    await send_main_menu(user_id, "Что дальше?")async def handle_help(user_id: int):    await send_max_message(user_id, HELP_TEXT)    await send_main_menu(user_id, "Что дальше?")async def start_book(user_id: int):    tenant = await get_current_tenant(user_id)    if not tenant:        await ask_tenant(user_id, "Сначала выберите заведение:")        return    today = date.today()    week_start = get_week_start(today)    await set_state(user_id, {"tenant_code": tenant.code, "step": "book_date_calendar"})    await show_week_calendar(user_id, week_start, "Шаг 1/4: выберите дату:", tenant)async def start_slots(user_id: int):    tenant = await get_current_tenant(user_id)    if not tenant:        await ask_tenant(user_id, "Сначала выберите заведение:")        return    today = date.today()    week_start = get_week_start(today)    await set_state(user_id, {"tenant_code": tenant.code, "step": "slots_date_calendar"})    await show_week_calendar(user_id, week_start, "📅 Выберите дату:", tenant)# ===== Обработка сообщений =====async def handle_message(raw_text: str, user_id: int):    logger.info(f"MAX message: '{raw_text}' from {user_id}")    parts = raw_text.split(maxsplit=1)    command = parts[0].lower() if parts else ""    args = parts[1].strip() if len(parts) > 1 else ""    if command == "/cancel":        await del_state(user_id)        await send_max_message(user_id, "Действие отменено.")        await send_main_menu(user_id, "Что дальше?")        return    state = await get_state(user_id)    if state:        step = state.get("step")        if step == "slots_date_calendar":            await del_state(user_id)            await handle_slots_request(user_id, raw_text)            return        if step == "book_name":            state["client_name"] = raw_text            state["step"] = "book_phone"            await set_state(user_id, state)            tenant = get_tenant_by_code(state.get("tenant_code"))            tenant_name = tenant.name if tenant else state.get("tenant_code")            await send_max_message(                user_id,                f"🏢 {tenant_name}\n"                f"👤 {state['employee_name']}\n"                f"📅 {state['date']} в {state['time']}\n"                f"🙍 {state['client_name']}\n\n"                f"Шаг 4/4: введите ваш телефон:"            )            return        if step == "book_phone":            state["client_phone"] = raw_text            tenant = get_tenant_by_code(state.get("tenant_code"))            try:                payload = {                    "employeeId": state["employee_id"],                    "date": state["date"],                    "time": state["time"],                    "clientName": state["client_name"],                    "clientPhone": state["client_phone"],                }                result = call_1c("createBooking", payload, tenant=tenant)                # Сохраняем напоминание с user_id                save_reminder(                    user_id=user_id,                    tenant_code=state["tenant_code"],                    employee_name=state["employee_name"],                    date_str=state["date"],                    time_str=state["time"],                )                await send_max_message(                    user_id,                    f"✅ Запись создана!\n\n"                    f"🏢 {tenant.name}\n"                    f"👤 {state['employee_name']}\n"                    f"📅 {state['date']}\n"                    f"⏰ {state['time']}\n"                    f"🙍 {state['client_name']}\n"                    f"📞 {state['client_phone']}\n\n"                    f"🔔 Мы напомним вам за час до визита."                )                logger.info(f"Booking result: {result}")            except HTTPException as e:                await send_max_message(user_id, f"Ошибка при создании записи: {e.detail}")            finally:                await del_state(user_id)                await send_main_menu(user_id, "Что дальше?")            return    if command == "/start":        await send_max_message(user_id, "Привет! Я бот для записи.\n\n" + HELP_TEXT)        await send_main_menu(user_id, "Что вы хотите сделать?")    elif command == "/help":        await handle_help(user_id)    elif command == "/slots":        if args and is_valid_date(clean_date(args)):            await handle_slots_request(user_id, args)        else:            await start_slots(user_id)    elif command == "/today":        today_str = date.today().strftime("%Y-%m-%d")        await handle_slots_request(user_id, today_str)    elif command == "/book":        await start_book(user_id)    elif command == "/contacts":        await handle_contacts(user_id)    elif command == "/master":        await handle_master(user_id)    else:        await send_max_message(user_id, "Неизвестная команда.")        await send_main_menu(user_id, "Что вы хотите сделать?")# ===== Обработка кнопок =====async def handle_callback(payload: str, user_id: int):    logger.info(f"Callback: '{payload}' from {user_id}")    if payload == "cancel":        await del_state(user_id)        await send_max_message(user_id, "Действие отменено.")        await send_main_menu(user_id, "Что дальше?")        return    if payload == "cal_noop":        return    if payload == "menu:choose_tenant":        await ask_tenant(user_id)        return    if payload.startswith("tenant:"):        tenant_code = payload.split(":", 1)[1]        tenant = get_tenant_by_code(tenant_code)        if not tenant:            await send_max_message(user_id, "❌ Заведение не найдено.")            return        state = await get_state(user_id) or {}        state["tenant_code"] = tenant_code        await set_state(user_id, state)        text = f"✅ Выбрано: {tenant.name}"        if tenant.address:            text += f"\n📍 {tenant.address}"        if tenant.phone:            text += f"\n📞 {tenant.phone}"        await send_max_message(user_id, text)        await send_main_menu(user_id, "Что дальше?")        return    if payload.startswith("menu:"):        action = payload.split(":", 1)[1]        if action == "slots":            await start_slots(user_id)        elif action == "book":            await start_book(user_id)        elif action == "master":            await handle_master(user_id)        elif action == "contacts":            await handle_contacts(user_id)        elif action == "help":            await handle_help(user_id)        return    state = await get_state(user_id)    if not state:        await send_max_message(user_id, "Сессия истекла. Начните заново.")        await send_main_menu(user_id, "Что вы хотите сделать?")        return    tenant = get_tenant_by_code(state.get("tenant_code"))    if not tenant:        await ask_tenant(user_id, "Сначала выберите заведение:")        return    if payload.startswith("cal_week:"):        _, date_str = payload.split(":", 1)        try:            week_start = datetime.strptime(date_str, "%Y-%m-%d").date()        except ValueError:            return        today = date.today()        min_week = get_week_start(today)        if week_start < min_week:            week_start = min_week        title = "📅 Выберите дату:" if state.get("step") == "slots_date_calendar" else "Шаг 1/4: выберите дату:"        await show_week_calendar(user_id, week_start, title, tenant)        return    if payload.startswith("cal_pick:"):        _, date_str = payload.split(":", 1)        try:            picked = datetime.strptime(date_str, "%Y-%m-%d").date()        except ValueError:            return        if picked < date.today():            await send_max_message(user_id, "❌ Нельзя выбрать прошедшую дату.")            return        step = state.get("step", "")        if step == "slots_date_calendar":            await del_state(user_id)            await handle_slots_request(user_id, date_str, tenant)            return        state["date"] = date_str        state["step"] = "book_employee"        await set_state(user_id, state)        await show_employees_keyboard(user_id, state, tenant)        return    if payload.startswith("emp:"):        emp_id = payload.split(":", 1)[1]        employees = state.get("employees", [])        emp_name = emp_id        for emp in employees:            if emp["id"] == emp_id:                emp_name = emp["name"]                break        state["employee_id"] = emp_id        state["employee_name"] = emp_name        await set_state(user_id, state)        await show_times_keyboard(user_id, state, tenant)        return    if payload.startswith("time:"):        time_val = payload.split(":", 1)[1]        state["time"] = time_val        state["step"] = "book_name"        await set_state(user_id, state)        await send_max_message(            user_id,            f"🏢 {tenant.name}\n"            f"👤 {state['employee_name']}\n"            f"📅 {state['date']} в {time_val}\n\n"            f"Введите ваше имя:"        )        return# ===== Фоновая задача напоминаний =====async def check_reminders():    logger.info("Проверка напоминаний...")    try:        reminders = get_pending_reminders()        if not reminders:            return        now = datetime.now()        soon = now + timedelta(hours=1)        for r in reminders:            try:                visit_dt = datetime.strptime(f"{r.date} {r.time}", "%Y-%m-%d %H:%M")            except ValueError:                continue            if now < visit_dt <= soon:                tenant = get_tenant_by_code(r.tenant_code)                tenant_name = tenant.name if tenant else r.tenant_code                text = (                    f"🔔 Напоминание о записи!\n\n"                    f"🏢 {tenant_name}\n"                    f"👤 {r.employee_name}\n"                    f"📅 {r.date}\n"                    f"⏰ {r.time}\n\n"                    f"Ждём вас через час!"                )                await send_max_message(r.user_id, text)                mark_reminded(r.id)                logger.info(f"Напоминание отправлено: user={r.user_id}, {r.date} {r.time}")    except Exception as e:        logger.error(f"Ошибка в check_reminders: {e}")# ===== Lifespan =====async def lifespan(app: FastAPI):    global redis_client, _http_client    logger.info("Запуск приложения...")    init_db()    logger.info("БД инициализирована")    redis_client = redis.Redis(        host=REDIS_HOST, port=REDIS_PORT, db=REDIS_DB, decode_responses=True    )    try:        await redis_client.ping()        logger.info(f"Redis подключён: {REDIS_HOST}:{REDIS_PORT}")    except Exception as e:        logger.error(f"Redis недоступен: {e}")        redis_client = None    _http_client = httpx.AsyncClient(verify="/etc/ssl/certs/ca-certificates.crt", timeout=10)    await set_bot_commands()    scheduler = AsyncIOScheduler()    scheduler.add_job(check_reminders, "interval", minutes=30)    scheduler.start()    logger.info("Шедулер напоминаний запущен (каждые 30 минут)")    yield    scheduler.shutdown()    await _http_client.aclose()    if redis_client:        await redis_client.aclose()    logger.info("Остановка приложения...")app = FastAPI(title="MAX Bot Backend", lifespan=lifespan)# ===== Проверка =====@app.get("/")def read_root():    return {"status": "ok", "message": "Backend is running"}@app.get("/health")def health_check():    result = {"backend": "ok", "redis": "unknown"}    result["redis"] = "connected" if redis_client else "disconnected"    tenants = get_all_tenants()    result["tenants"] = [{"code": t.code, "name": t.name} for t in tenants]    return result# ===== API для мини-приложения =====@app.get("/api/tenants")def get_tenants():    tenants = get_all_tenants()    return {"tenants": [        {"code": t.code, "name": t.name, "type": t.type, "address": t.address, "phone": t.phone}        for t in tenants    ]}@app.post("/api/slots")def get_slots(req: SlotRequest):    tenant = None    if req.tenant_code:        tenant = get_tenant_by_code(req.tenant_code)    if req.employee:        free = get_free_slots(req.date, req.employee, tenant)        return {"date": req.date, "employee": req.employee, "slots": free}    employees = get_employees(tenant=tenant)    result = []    for emp in employees:        result.append({            "employeeId": emp["id"],            "employeeName": emp["name"],            "slots": get_free_slots(req.date, emp["id"], tenant),        })    return {"date": req.date, "employees": result}@app.post("/api/booking")def create_booking(req: BookingRequest):    tenant = None    if req.tenant_code:        tenant = get_tenant_by_code(req.tenant_code)    payload = {        "employeeId": req.employee_id,        "date": req.date,        "time": req.time,        "clientName": req.client_name,        "clientPhone": req.client_phone,    }    result = call_1c("createBooking", payload, tenant=tenant)    # Сохраняем напоминание, если есть user_id (запись из мини-приложения внутри MAX)    if req.user_id:        employee_name = req.employee_name or req.employee_id        save_reminder(            user_id=req.user_id,            tenant_code=req.tenant_code or "unknown",            employee_name=employee_name,            date_str=req.date,            time_str=req.time,        )        logger.info(f"Reminder saved from miniapp: user={req.user_id}, {req.date} {req.time}")    return {"status": "created", "result": result}# ===== Вебхук =====@app.post("/webhook")async def max_webhook(request: Request, x_max_bot_api_secret: Optional[str] = Header(None)):    expected_secret = os.getenv("BOT_WEBHOOK_SECRET")    if expected_secret and x_max_bot_api_secret != expected_secret:        raise HTTPException(status_code=403, detail="Invalid secret")    try:        update = await request.json()    except Exception:        raise HTTPException(status_code=400, detail="Invalid JSON")    logger.info(f"Получено событие от MAX: {update}")    update_type = update.get("update_type")    if update_type == "message_created":        message = update.get("message", {})        text = message.get("body", {}).get("text", "")        user_id = message.get("sender", {}).get("user_id")        if user_id:            await handle_message(text, user_id)    elif update_type == "message_callback":        callback = update.get("callback", {})        payload = callback.get("payload", "")        user = callback.get("user", {})        user_id = user.get("user_id")        if user_id and payload:            await handle_callback(payload, user_id)    elif update_type == "bot_started":        logger.info("Бот запущен новым пользователем")    return JSONResponse({"ok": True})# ===== Точка входа =====if __name__ == "__main__":    import uvicorn    uvicorn.run(        "main:app",        host=os.getenv("APP_HOST", "0.0.0.0"),        port=int(os.getenv("APP_PORT", "8000")),        reload=False,    )